WITH sessions_by_customer AS (SELECT customer_id, COUNT(CASE WHEN country = 'US' THEN 1 END) AS us_count, COUNT(DISTINCT country) AS unique_countrys FROM sessions GROUP BY customer_id) SELECT c.id, c.city, sbc.us_count, sbc.unique_countrys FROM customers c INNER JOIN sessions_by_customer sbc ON c.id = sbc.customer_id WHERE sbc.unique_countrys >= 6 ORDER BY sbc.unique_countrys DESC;
